    # Robust count islands implementation that handles empty grid and jagged rows.
    if not grid:
        return 0
    n = len(grid)
    visited = set()
    def neighbors(i, j):
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

