def solve(grid):
    """Count islands (connected groups of 1s) in a possibly jagged binary grid.
    Cells are connected up, down, left, right.
    Returns 0 for empty grid or non‑list input.
    """
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    # Determine column count per row; we treat missing cells as 0
    visited = []
    for r in range(rows):
        if isinstance(grid[r], (list, tuple)):
            visited.append([False] * len(grid[r]))
        else:
            visited.append([])
    def get_cell(i, j):
        if i < 0 or i >= rows:
            return 0
        row = grid[i]
        if not isinstance(row, (list, tuple)):
            return 0
        if j < 0 or j >= len(row):
            return 0
        return row[j]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= rows:
                continue
            row = grid[x]
            if not isinstance(row, (list, tuple)):
                continue
            if y < 0 or y >= len(row):
                continue
            if visited[x][y] or row[y] != 1:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(rows):
        row = grid[i]
        if not isinstance(row, (list, tuple)):
            continue
        for j in range(len(row)):
            if row[j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

